CREATE FUNCTION public.save_reviewed_transactions(doc_id uuid,rows jsonb,selected_currency text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.documents WHERE id=doc_id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Document not found'; END IF; IF jsonb_array_length(rows)<1 OR jsonb_array_length(rows)>5000 THEN RAISE EXCEPTION 'Review between 1 and 5000 rows'; END IF; DELETE FROM public.transactions WHERE document_id=doc_id AND user_id=auth.uid(); INSERT INTO public.transactions(user_id,document_id,date,description,reference,debit,credit,balance,category,currency) SELECT auth.uid(),doc_id,(r->>'date')::date,r->>'description',r->>'reference',(r->>'debit')::numeric,(r->>'credit')::numeric,(r->>'balance')::numeric,coalesce(nullif(r->>'category',''),'Uncategorised'),selected_currency FROM jsonb_array_elements(rows) r; UPDATE public.documents SET status='processed',currency=selected_currency,error_message=NULL WHERE id=doc_id AND user_id=auth.uid(); END; $$;
REVOKE ALL ON FUNCTION public.save_reviewed_transactions(uuid,jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_reviewed_transactions(uuid,jsonb,text) TO authenticated;